import pickle
import json
from typing import Any, Dict, Optional

class UserCache:
    def __init__(self, max_size: int = 10000):
        self.cache: Dict[int, Any] = {}
        self.max_size = max_size

    def get(self, user_id: int, db_fetch_fn) -> Optional[Dict]:
        """Retrieve user from cache or database."""
        if user_id in self.cache:
            return self.cache[user_id]

        # Fetch from database and cache the result
        user_data = db_fetch_fn(user_id)
        if user_data:
            self.cache[user_id] = user_data
            if len(self.cache) > self.max_size:
                # Simple eviction: remove first entry
                self.cache.pop(next(iter(self.cache)))

        return user_data

    def cache_from_serialized(self, user_id: int, serialized_data: bytes) -> None:
        """Cache a user object from serialized bytes (e.g., from Redis)."""
        # Deserialize directly for speed
        user_obj = pickle.loads(serialized_data)
        self.cache[user_id] = user_obj

    def get_cached_object(self, user_id: int) -> Optional[Any]:
        return self.cache.get(user_id)

# Usage
cache = UserCache()
user = cache.cache_from_serialized(123, some_bytes_from_redis)
